priorityScores.push(make({id:'pelod2',name:'PELOD-2',specialty:'Terapia intensiva',population:'Pediatria · UTI',subtitle:'Disfunção de órgãos pediátrica',max:33,scope:'Crianças criticamente enfermas; selecionar a categoria documentada de cada componente. PAM e creatinina usam limites por idade do quadro original.',fields:[s('gcs','Glasgow',[[0,'≥11'],[1,'5–10'],[4,'3–4']]),s('pupil','Pupilas',[[0,'Reativas'],[5,'Ambas não reativas >3 mm']]),s('lactate','Lactato',[[0,'<5 mmol/L'],[1,'5–10,9'],[4,'≥11']]),s('map','PAM · categoria etária PELOD-2',[[0,'Sem ponto'],[2,'Faixa de 2 pontos'],[3,'Faixa de 3 pontos'],[6,'Faixa de 6 pontos']],'Conferir limiar da idade no quadro original.'),s('creat','Creatinina · categoria etária',[[0,'Abaixo do limite'],[2,'No/acima do limite']],'Conferir limiar da idade.'),s('pf','PaO₂/FiO₂',[[0,'>60'],[2,'≤60']]),s('pco2','PaCO₂',[[0,'<59 mmHg'],[1,'59–94 mmHg'],[3,'≥95 mmHg']]),y('vent','Ventilação invasiva',3),s('wbc','Leucócitos',[[0,'>2.000/mm³'],[2,'≤2.000/mm³']]),s('platelet','Plaquetas',[[0,'≥142.000/mm³'],[1,'77.000–141.999/mm³'],[2,'≤76.000/mm³']])],action:'Quantificar disfunção orgânica e acompanhar tendência. Não fornece decisão terapêutica isolada.',limits:'Não é escore de alerta precoce. Aplicar critérios etários originais e condições de medida; sedação e intervenções podem alterar componentes. Probabilidade de morte depende de calibração populacional.',sources:[R.pelod,ref('PELOD-2 original · PMID 23685639','https://pubmed.ncbi.nlm.nih.gov/23685639/')]}));
