priorityScores.push(make({id:'mews',name:'MEWS',specialty:'Terapia intensiva',population:'Adultos',subtitle:'Modified Early Warning Score',max:14,scope:'Adultos hospitalizados. Pontuar a pior categoria contemporânea de PAS, FC, FR, temperatura e consciência.',fields:[meta(n('sbp','Pressão arterial sistólica (mmHg)',20,300,1)),meta(n('hr','Frequência cardíaca (bpm)',10,250,1)),meta(n('rr','Frequência respiratória (/min)',1,80,1)),meta(n('temp','Temperatura (°C)',25,45,.1)),meta(s('avpu','Consciência · AVPU',[[0,'Alerta'],[1,'Responde à voz'],[2,'Responde à dor'],[3,'Não responde']]))],formula:'Categorias fisiológicas MEWS; total de 0 a 14.',compute:x=>{const sbp=x.sbp<=70?3:x.sbp<=80?2:x.sbp<=100?1:x.sbp<200?0:2,hr=x.hr<=40?2:x.hr<=50?1:x.hr<=100?0:x.hr<=110?1:x.hr<130?2:3,rr=x.rr<9?2:x.rr<=14?0:x.rr<=20?1:x.rr<30?2:3,temp=x.temp<35?2:x.temp<38.5?0:2,total=sbp+hr+rr+temp+x.avpu;return result(total,total>=5?'Alerta elevado':total>=3?'Alerta intermediário':'Baixa pontuação',total>=5?'Avaliação clínica imediata e escalonamento conforme protocolo local.':'Interpretar tendência e qualquer parâmetro isoladamente grave.',`PAS=${sbp}; FC=${hr}; FR=${rr}; T=${temp}; AVPU=${x.avpu}`,total>=5?'high':total>=3?'medium':'low');},limits:'Os gatilhos variam por instituição e MEWS não deve retardar resposta a preocupação clínica. Não validado como regra universal para alta.',sources:[R.mews]}));
priorityScores.push(make({id:'rems',name:'REMS',specialty:'Medicina de urgência',population:'Adultos',subtitle:'Rapid Emergency Medicine Score',max:26,scope:'Adultos atendidos na emergência. Usa idade, PAM, FC, FR, SpO₂ e Glasgow.',fields:[meta(n('age','Idade (anos)',18,110,1)),meta(n('map','Pressão arterial média (mmHg)',10,250,1)),meta(n('hr','Frequência cardíaca (bpm)',10,250,1)),meta(n('rr','Frequência respiratória (/min)',1,80,1)),meta(n('spo2','SpO₂ (%)',20,100,1)),meta(n('gcs','Glasgow',3,15,1))],formula:'Soma de seis categorias REMS; 0–26.',compute:x=>{const age=x.age<45?0:x.age<55?2:x.age<65?3:x.age<75?5:6,map=x.map<50||x.map>=160?4:x.map>=130?3:x.map<70||x.map>=110?2:0,hr=x.hr<40||x.hr>=180?4:x.hr<55||x.hr>=140?3:x.hr<70||x.hr>=110?2:0,rr=x.rr<6||x.rr>=50?4:x.rr>=35?3:x.rr<10?2:x.rr<12||x.rr>=25?1:0,spo2=x.spo2<75?4:x.spo2<=85?3:x.spo2<=89?1:0,gcs=x.gcs<=4?4:x.gcs<=7?3:x.gcs<=10?2:x.gcs<=13?1:0,total=age+map+hr+rr+spo2+gcs;return result(total,total>=10?'Risco fisiológico elevado':total>=6?'Risco intermediário':'Menor pontuação','Priorizar estabilização e usar como complemento à avaliação e ao protocolo institucional.',`idade=${age}; PAM=${map}; FC=${hr}; FR=${rr}; SpO₂=${spo2}; GCS=${gcs}`,total>=10?'high':total>=6?'medium':'low');},limits:'Estratifica risco populacional, não determina destino individual. Oxigênio suplementar, intoxicação e doença crônica afetam a interpretação.',sources:[R.mews]}));
priorityScores.push(make({id:'cam-icu',name:'CAM-ICU',specialty:'Terapia intensiva',population:'Adultos · UTI',subtitle:'Delirium em pacientes críticos',range:'Positivo / negativo / não avaliável',unit:'resultado',resultScale:false,max:1,scope:'Aplicar em paciente com RASS ≥−3. Examinar início agudo/flutuação, desatenção, alteração da consciência e pensamento desorganizado.',fields:[meta(s('rass','RASS permite avaliação?',[[0,'Não · RASS −4/−5'],[1,'Sim · RASS ≥−3']])) ,meta(y('f1','1. Início agudo ou curso flutuante')),meta(y('f2','2. Desatenção')),meta(y('f3','3. Nível de consciência alterado')),meta(y('f4','4. Pensamento desorganizado'))],formula:'Positivo = característica 1 + 2 + (3 ou 4).',compute:x=>{if(!x.rass)return {...result(0,'Não avaliável','Tratar coma/sedação e repetir quando RASS permitir.','RASS −4/−5','medium'),displayValue:'Não avaliável'};const pos=!!(x.f1&&x.f2&&(x.f3||x.f4));return {...result(pos?1:0,pos?'CAM-ICU positivo':'CAM-ICU negativo',pos?'Investigar causas, revisar fármacos e implementar medidas não farmacológicas conforme protocolo.':'Repetir seriado; resultado negativo isolado não exclui delirium flutuante.',`F1=${x.f1}; F2=${x.f2}; F3=${x.f3}; F4=${x.f4}`,pos?'high':'low'),displayValue:pos?'Positivo':'Negativo'};},limits:'Exige treinamento e teste padronizado de atenção/pensamento. Não diagnostica etiologia nem substitui avaliação clínica.',sources:[ref('Vanderbilt/CIBS · CAM-ICU · fluxograma oficial 2023','https://cdn.prod.website-files.com/5b0849daec50243a0a1e5e0c/656f9d329df092cd23ca69bf_CAM-ICU-tools-2023_flowsheet.pdf'),ref('Vanderbilt/CIBS · CAM-ICU e RASS · cartões oficiais','https://cdn.prod.website-files.com/5b0849daec50243a0a1e5e0c/64494326d62bbde72c3bafc4_CAM-ICU-Pocket-Cards.pdf')]}));
priorityScores.push(make({id:'icdsc',name:'ICDSC',specialty:'Terapia intensiva',population:'Adultos · UTI',subtitle:'Intensive Care Delirium Screening Checklist',max:8,scope:'Avaliar ao longo de todo o turno em paciente avaliável; componentes não precisam coexistir. Itens de sono e flutuação usam também as 24 h anteriores. Um ponto por característica presente.',fields:['Alteração do nível de consciência','Desatenção','Desorientação','Alucinação/delírio/psicose','Agitação ou retardo psicomotor','Fala ou humor inadequado','Distúrbio sono–vigília','Flutuação dos sintomas'].map((label,i)=>y('item'+i,label)),bands:[b(0,'Sem sinais no checklist','low','Manter rastreio seriado.'),b(3,'Delirium subsindrômico possível','medium','Um a três pontos justificam avaliação clínica e prevenção.'),b(8,'Delirium provável','high','≥4: investigar precipitantes e manejar conforme protocolo.')],limits:'Não aplicar durante coma profundo; exige avaliação longitudinal. Um resultado positivo é triagem, não etiologia.',sources:[ref('Vanderbilt/CIBS · ICDSC · checklist institucional completo','https://cdn.prod.website-files.com/5b0849daec50243a0a1e5e0c/5bad3e04cc14601f7c2dc05f_2013-Tufts-ICU-Delirium-Screening-Checklist.pdf')]}));
priorityScores.push(make({id:'mrc-sum',name:'MRC Sum Score',specialty:'Terapia intensiva',subtitle:'Fraqueza adquirida na UTI',max:60,scope:'Paciente cooperativo. Avaliar bilateralmente abdução de ombro, flexão de cotovelo, extensão de punho, flexão de quadril, extensão de joelho e dorsiflexão do tornozelo.',fields:['Ombro bilateral','Cotovelo bilateral','Punho bilateral','Quadril bilateral','Joelho bilateral','Tornozelo bilateral'].map((label,i)=>n('muscle'+i,label,0,10,1,'Soma dos lados direito e esquerdo, cada um de 0 a 5.')),formula:'Seis grupos musculares bilateralmente; total 0–60.',compute:x=>{const total=Object.values(x).reduce((a,v)=>a+v,0);return result(total,total<36?'Fraqueza grave provável':total<48?'Fraqueza adquirida na UTI provável':'Sem corte de fraqueza atingido',total<48?'Confirmar técnica, cooperação e causas neuromusculares; planejar mobilização e investigação.':'Acompanhar tendência conforme contexto.',Object.entries(x).map(([k,v])=>`${k}=${v}`).join('; '),total<48?'high':'low');},limits:'Delirium, dor, sedação, lesão focal e baixa cooperação invalidam a medida. O diagnóstico requer quadro clínico compatível.',sources:[R.mrc]}));
priorityScores.push(continuous({id:'rsbi',name:'Índice de Tobin · RSBI',specialty:'Terapia intensiva',population:'Ventilação mecânica · adultos',subtitle:'FR/volume corrente no desmame',scope:'Durante teste de respiração espontânea, medir FR e volume corrente espontâneo em litros, nas condições padronizadas do serviço.',fields:[meta(n('rr','Frequência respiratória (/min)',1,80,.1)),meta(n('vt','Volume corrente (mL)',50,2000,1))],formula:'RSBI = FR ÷ volume corrente em litros.',compute:x=>{const total=x.rr/(x.vt/1000);return result(total,total<=105?'Abaixo ou igual ao corte histórico':'Acima do corte histórico',total<=105?'Compatível com maior chance de sucesso, se todos os demais critérios forem favoráveis.':'Maior risco de falha; corrigir causas e integrar ao teste completo.',`FR ${x.rr} ÷ VT ${(x.vt/1000).toFixed(3)} L`,total>105?'medium':'low');},limits:'Corte 105 não decide extubação. Tosse, secreções, proteção de via aérea, troca gasosa, carga cardíaca e técnica de medida são essenciais.',sources:[R.rsbi]}));
priorityScores.push(continuous({id:'pf-ratio',name:'Relação PaO₂/FiO₂',specialty:'Terapia intensiva',subtitle:'Índice de oxigenação arterial',scope:'Obter PaO₂ e FiO₂ contemporâneas; registrar PEEP/suporte e altitude.',fields:[meta(n('pao2','PaO₂ (mmHg)',10,800,.1)),meta(n('fio2','FiO₂ (%)',21,100,.1))],formula:'P/F = PaO₂ ÷ FiO₂ em fração.',compute:x=>{const total=100*x.pao2/x.fio2;return result(total,total<=100?'Hipoxemia muito grave':total<=200?'Hipoxemia grave':total<=300?'Hipoxemia moderada':'Relação acima de 300','Interpretar com PEEP, ventilação, imagem e contexto; avaliar insuficiência respiratória imediatamente quando baixa.',`${x.pao2} ÷ ${(x.fio2/100).toFixed(3)}`,total<=200?'high':total<=300?'medium':'low');},limits:'Não diagnostica SDRA isoladamente. FiO₂ estimada em dispositivos de baixo fluxo é imprecisa.',sources:[ref('Definição global de SDRA · 2024 · PMID 38245862','https://pubmed.ncbi.nlm.nih.gov/38245862/')]}));
priorityScores.push(continuous({id:'sf-ratio',name:'Relação SpO₂/FiO₂',specialty:'Terapia intensiva',subtitle:'Índice não invasivo de oxigenação',scope:'SpO₂ e FiO₂ contemporâneas, preferencialmente com curva confiável e SpO₂ ≤97%.',fields:[meta(n('spo2','SpO₂ (%)',50,100,.1)),meta(n('fio2','FiO₂ (%)',21,100,.1))],formula:'S/F = SpO₂ ÷ FiO₂ em fração.',compute:x=>{const total=100*x.spo2/x.fio2;return result(total,total<=148?'Oxigenação muito comprometida':total<=235?'Oxigenação comprometida':total<=315?'Faixa intermediária':'Relação acima de 315','Confirmar gravidade, suporte e necessidade de gasometria conforme contexto.',`${x.spo2} ÷ ${(x.fio2/100).toFixed(3)}`,total<=235?'high':total<=315?'medium':'low');},limits:'Os equivalentes 315/235/148 são aproximações e perdem precisão com SpO₂ alta, má perfusão, dis-hemoglobina ou FiO₂ incerta.',sources:[pmc('PMC3776410','Relação S/F e substituição da relação P/F')]}));
priorityScores.push(continuous({id:'modified-shock-index',name:'Índice de choque modificado',specialty:'Medicina de urgência',population:'Adultos',subtitle:'FC/pressão arterial média',scope:'Triagem hemodinâmica complementar. Usar sinais vitais contemporâneos.',fields:[meta(n('hr','Frequência cardíaca (bpm)',10,250,1)),meta(n('map','Pressão arterial média (mmHg)',10,200,1))],formula:'MSI = FC ÷ PAM.',compute:x=>{const total=x.hr/x.map;return result(total,total>1.3?'Índice elevado':total<0.7?'Índice baixo':'Faixa de referência observacional','Investigar perfusão, causa e tendência; agir sobre instabilidade independentemente do índice.',`${x.hr} ÷ ${x.map}`,total>1.3?'high':total<.7?'medium':'low');},limits:'Pontos de corte variam por cenário. Betabloqueio, marcapasso, gestação e arritmia alteram a interpretação.',sources:[pmc('PMC9277969','Modified Shock Index na emergência')]}));
priorityScores.push(continuous({id:'age-shock-index',name:'Índice de choque ajustado à idade',specialty:'Medicina de urgência',population:'Adultos',subtitle:'Idade × FC/PAS',scope:'Adultos, sobretudo trauma e emergência. Usar idade em anos e sinais vitais contemporâneos.',fields:[meta(n('age','Idade (anos)',18,110,1)),meta(n('hr','Frequência cardíaca (bpm)',10,250,1)),meta(n('sbp','Pressão arterial sistólica (mmHg)',20,300,1))],formula:'ASI = idade × (FC ÷ PAS).',compute:x=>{const total=x.age*x.hr/x.sbp;return result(total,total>=50?'Índice elevado':'Abaixo de 50','Valor elevado reforça risco e necessidade de avaliação rápida; não substitui critérios de choque/trauma.',`${x.age} × ${x.hr}/${x.sbp}`,total>=50?'high':'low');},limits:'Corte e desempenho dependem da população. Fármacos e arritmia podem mascarar resposta cronotrópica.',sources:[pmc('PMC10841476','Age Shock Index em trauma')]}));
priorityScores.push(make({id:'murray-lis',name:'Murray Lung Injury Score',specialty:'Terapia intensiva',population:'Adultos',subtitle:'Lesão pulmonar · quatro componentes',max:4,range:'0–4',unit:'média',resultScale:false,scope:'Avaliar radiografia, P/F, PEEP e complacência estática contemporâneos. A pontuação final é a média dos componentes disponíveis.',fields:[meta(n('cxr','Quadrantes com infiltrado alveolar',0,4,1)),meta(n('pf','Relação PaO₂/FiO₂',20,700,1)),meta(n('peep','PEEP (cmH₂O)',0,30,1)),meta(n('compliance','Complacência estática (mL/cmH₂O)',1,150,1))],formula:'Média de: quadrantes; categoria P/F; categoria PEEP; categoria complacência.',compute:x=>{const pf=x.pf>=300?0:x.pf>=225?1:x.pf>=175?2:x.pf>=100?3:4,peep=x.peep<=5?0:x.peep<=8?1:x.peep<=11?2:x.peep<=14?3:4,comp=x.compliance>=80?0:x.compliance>=60?1:x.compliance>=40?2:x.compliance>=20?3:4,total=(x.cxr+pf+peep+comp)/4;return result(total,total>2.5?'Lesão pulmonar grave pelo escore':total>=1?'Lesão leve a moderada':'Sem lesão pelo escore','Integrar aos critérios atuais de SDRA, ventilação protetora e evolução.',`RX=${x.cxr}; P/F=${pf}; PEEP=${peep}; Cst=${comp}`,total>2.5?'high':total>=1?'medium':'low');},limits:'Escore histórico; não substitui definição atual de SDRA. Radiografia e complacência têm variabilidade de medida.',sources:[R.murray]}));
priorityScores.push(make({id:'hacor',name:'HACOR',specialty:'Terapia intensiva',population:'Adultos hipoxêmicos em VNI',subtitle:'Risco de falha da ventilação não invasiva',max:25,scope:'HACOR original: adultos com insuficiência respiratória hipoxêmica, avaliados após 1 h de VNI. Componentes: FC, acidose, consciência, oxigenação e FR. Não usar estes pesos como a variante específica de DPOC.',fields:[meta(n('hr','Frequência cardíaca (bpm)',20,250,1)),meta(n('ph','pH arterial',6.8,7.8,.01)),meta(n('gcs','Glasgow',3,15,1)),meta(n('pf','Relação PaO₂/FiO₂',20,700,1)),meta(n('rr','Frequência respiratória (/min)',1,80,1))],formula:'H + A + C + O + R conforme categorias originais.',compute:x=>{const hr=x.hr>120?1:0,ph=x.ph>=7.35?0:x.ph>=7.30?2:x.ph>=7.25?3:4,gcs=x.gcs===15?0:x.gcs>=13?2:x.gcs>=11?5:10,pf=x.pf>200?0:x.pf>175?2:x.pf>150?3:x.pf>125?4:x.pf>100?5:6,rr=x.rr<=30?0:x.rr<=35?1:x.rr<=40?2:x.rr<=45?3:4,total=hr+ph+gcs+pf+rr;return result(total,total>5?'Alto risco de falha':'Menor risco pelo corte original',total>5?'Reavaliar imediatamente resposta e não atrasar intubação quando indicada.':'Manter monitorização estreita e reavaliar em série.',`H=${hr}; A=${ph}; C=${gcs}; O=${pf}; R=${rr}`,total>5?'high':'medium');},limits:'Validado em populações específicas de VNI e em tempos determinados. Não é indicação automática de intubação nem deve atrasá-la.',sources:[R.hacor,ref('HACOR original · Supplementary Table 2 · pesos','https://media.springernature.com/original/springer-static/esm/art%3A10.1007%2Fs00134-016-4601-3/MediaObjects/134_2016_4601_MOESM4_ESM.doc')]}));

