priorityScores.push(make({id:'csrs',name:'Canadian Syncope Risk Score',specialty:'Medicina de urgência',population:'Pacientes ≥16 anos',subtitle:'Evento adverso grave em 30 dias',range:'−3 a 11',max:11,scope:'Aplicar após investigação na emergência e antes da decisão de destino, em síncope compatível com critérios da validação.',fields:[meta(y('vasovagal','Predisposição vasovagal',-1)),y('heart','História de cardiopatia'),y('bp','Qualquer PAS <90 ou >180 mmHg',2),y('troponin','Troponina >percentil 99',2),y('axis','Eixo QRS <−30° ou >100°'),y('qrs','QRS >130 ms'),y('qtc','QTc >480 ms',2),meta(s('dx','Diagnóstico na emergência',[[0,'Outro'],[-2,'Síncope vasovagal'],[2,'Síncope cardíaca']]))],formula:'−1 predisposição vasovagal + variáveis clínicas/ECG + diagnóstico da emergência.',compute:x=>{const total=Object.values(x).reduce((a,v)=>a+v,0),label=total<=-2?'Risco muito baixo':total<=0?'Risco baixo':total<=3?'Risco intermediário':total<=5?'Risco alto':'Risco muito alto';return result(total,label,'Usar probabilidade validada e protocolo local para observação, monitorização e seguimento; investigar diagnósticos tempo-dependentes.',Object.entries(x).map(([k,v])=>`${k}=${v}`).join('; '),total>=4?'high':total>=1?'medium':'low');},limits:'Não aplicar se causa grave já evidente, perda de consciência >5 min, ausência de recuperação do estado mental basal, convulsão evidente, trauma importante, trauma craniano causando perda de consciência ou intoxicação. Não extrapolar automaticamente a quase-síncope. Troponina depende do ensaio; critérios/itens desconhecidos devem ser explicitados.',sources:[ref('CMAJ · CSRS original · definições e exclusões','https://www.cmaj.ca/content/188/12/E289'),pmc('PMC8224075','Medicina 2021 · CSRS · tabela 4 e figura 1')]}));
