// CLÍNICA MÉDICA, GERIATRIA E SEGURANÇA HOSPITALAR
priorityScores.push(make({id:'charlson-age',name:'Charlson · ajustado à idade',specialty:'Clínica médica',population:'Adultos',subtitle:'Carga de comorbidades',max:37,scope:'Adultos com comorbidades documentadas. Evitar dupla contagem de gravidades mutuamente exclusivas da mesma doença.',fields:[meta(s('age','Idade',[[0,'<50 anos'],[1,'50–59'],[2,'60–69'],[3,'70–79'],[4,'≥80']])),y('mi','Infarto do miocárdio'),y('chf','Insuficiência cardíaca'),y('pvd','Doença vascular periférica'),y('cvd','Doença cerebrovascular'),y('dementia','Demência'),y('copd','Doença pulmonar crônica'),y('ctd','Doença do tecido conjuntivo'),y('ulcer','Doença ulcerosa péptica'),meta(s('diabetes','Diabetes',[[0,'Ausente'],[1,'Sem lesão de órgão'],[2,'Com lesão de órgão']])) ,meta(s('liver','Doença hepática',[[0,'Ausente'],[1,'Leve'],[3,'Moderada/grave']])) ,y('renal','Doença renal moderada/grave',2),y('hemiplegia','Hemiplegia',2),y('leukemia','Leucemia',2),y('lymphoma','Linfoma',2),meta(s('cancer','Tumor sólido',[[0,'Ausente'],[2,'Localizado'],[6,'Metastático']])) ,y('aids','AIDS',6)],action:'Usar para ajuste de risco, descrição de população e planejamento; interpretar o modelo específico que incorpora o índice.',limits:'Pesos e definições dependem da versão/codificação. Não é estimativa individual autônoma de sobrevida nem deve limitar cuidado.',sources:[R.charlson]}));
priorityScores.push(ordinal('clinical-frailty-scale','Clinical Frailty Scale · CFS','Clínica médica',[[1,'Muito ativo'],[2,'Ativo'],[3,'Controlando bem'],[4,'Vivendo com fragilidade muito leve'],[5,'Vivendo com fragilidade leve'],[6,'Vivendo com fragilidade moderada'],[7,'Vivendo com fragilidade grave'],[8,'Vivendo com fragilidade muito grave'],[9,'Doente terminal']],'CFS v2.0: aplicar em adultos com ≥65 anos, com informações funcionais confiáveis do estado basal cerca de duas semanas antes da doença aguda. No nível 9, doença terminal atual prevalece sobre o estado basal.',[R.frailty,ref('Dalhousie University · Clinical Frailty Scale','https://www.dal.ca/sites/gmr/our-tools/clinical-frailty-scale.html')],'Não pontuar pela aparência durante doença aguda. Em pessoas jovens, deficiência estável ou transtorno do neurodesenvolvimento, a validade pode ser limitada.','nível'));
priorityScores.push(make({id:'frail-scale',name:'FRAIL Scale',specialty:'Clínica médica',population:'Adultos mais velhos',subtitle:'Triagem de fragilidade',max:5,scope:'Triagem breve do estado basal em adultos mais velhos.',fields:[y('fatigue','Fadiga'),y('resistance','Dificuldade para subir um lance de escadas'),y('ambulation','Dificuldade para caminhar um quarteirão'),y('illness','Cinco ou mais doenças'),y('loss','Perda de peso >5%')],bands:[b(0,'Robusto','low','Promover atividade e reavaliar conforme contexto.'),b(2,'Pré-fragilidade','medium','Investigar causas reversíveis e planejar intervenção multidimensional.'),b(5,'Fragilidade','high','≥3: avaliação geriátrica ampla e planejamento individualizado.')],limits:'Triagem não substitui avaliação geriátrica, cognição, nutrição e funcionalidade. Confirmar período de referência para perda de peso.',sources:[pmc('PMC9437258','FRAIL Scale · revisão e validação')]}));
priorityScores.push(make({id:'braden',name:'Braden',specialty:'Clínica médica',population:'Adultos hospitalizados',subtitle:'Risco de lesão por pressão',max:23,range:'6–23',scope:'Avaliar percepção sensorial, umidade, atividade, mobilidade, nutrição e fricção/cisalhamento.',fields:[s('sensory','Percepção sensorial',[[1,'Completamente limitada'],[2,'Muito limitada'],[3,'Levemente limitada'],[4,'Sem limitação']]),s('moisture','Umidade',[[1,'Constantemente úmida'],[2,'Muito úmida'],[3,'Ocasionalmente úmida'],[4,'Raramente úmida']]),s('activity','Atividade',[[1,'Acamado'],[2,'Restrito à cadeira'],[3,'Caminha ocasionalmente'],[4,'Caminha frequentemente']]),s('mobility','Mobilidade',[[1,'Completamente imóvel'],[2,'Muito limitada'],[3,'Levemente limitada'],[4,'Sem limitação']]),s('nutrition','Nutrição',[[1,'Muito pobre'],[2,'Provavelmente inadequada'],[3,'Adequada'],[4,'Excelente']]),s('friction','Fricção/cisalhamento',[[1,'Problema'],[2,'Problema potencial'],[3,'Sem problema aparente']])],formula:'Cinco domínios 1–4 + fricção 1–3; total 6–23, menor é pior.',compute:x=>{const total=Object.values(x).reduce((a,v)=>a+v,0),label=total<=9?'Risco muito alto':total<=12?'Risco alto':total<=14?'Risco moderado':total<=18?'Em risco':'Acima dos cortes usuais';return result(total,label,'Implementar prevenção individualizada por domínio e reavaliar após mudanças clínicas.',Object.entries(x).map(([k,v])=>`${k}=${v}`).join('; '),total<=12?'high':total<=18?'medium':'low');},limits:'Cortes variam por cenário; risco clínico e lesão existente prevalecem. Não usar total para omitir inspeção da pele ou reposicionamento.',sources:[R.braden]}));
priorityScores.push(make({id:'morse',name:'Morse Fall Scale',specialty:'Clínica médica',population:'Adultos hospitalizados',subtitle:'Risco de queda',max:125,scope:'Triagem hospitalar de quedas; aplicar definições e cortes institucionais.',fields:[y('history','História de queda recente',25),y('secondary','Diagnóstico secundário',15),s('aid','Auxílio para deambular',[[0,'Nenhum/repouso/auxílio profissional'],[15,'Muletas/bengala/andador'],[30,'Apoia-se em mobiliário']]),y('iv','Acesso venoso ou heparin lock',20),s('gait','Marcha/transferência',[[0,'Normal/repouso/imóvel'],[10,'Fraca'],[20,'Comprometida']]),y('mental','Superestima ou esquece limitações',15)],bands:[b(24,'Baixo risco','low','Aplicar medidas universais e reavaliar.'),b(44,'Risco moderado','medium','Adicionar intervenções direcionadas.'),b(125,'Alto risco','high','≥45: plano intensivo de prevenção conforme protocolo.')],limits:'Cortes e definições podem variar. Queda prévia, delirium e fármacos exigem ação mesmo com pontuação baixa.',sources:[pmc('PMC8649260','Morse Fall Scale · desempenho e componentes')]}));
priorityScores.push(continuous({id:'meld-na',name:'MELD-Na',specialty:'Clínica médica',population:'Adultos com doença hepática',subtitle:'Gravidade hepática com sódio',range:'6–40',unit:'pontos',scope:'Adultos com cirrose em contexto compatível com a fórmula clássica MELD-Na. Inserir valores contemporâneos.',fields:[meta(n('bili','Bilirrubina total (mg/dL)',.1,80,.01)),meta(n('inr','INR',.5,10,.01)),meta(n('creat','Creatinina (mg/dL)',.1,15,.01)),meta(n('sodium','Sódio (mmol/L)',100,180,.1)),meta(y('dialysis','Diálise ≥2 vezes na última semana'))],formula:'MELD(i)=3,78 ln(bili)+11,2 ln(INR)+9,57 ln(creat)+6,43; depois ajuste pelo Na 125–137.',compute:x=>{const bili=Math.max(1,x.bili),inr=Math.max(1,x.inr),creat=x.dialysis?4:Math.min(4,Math.max(1,x.creat)),na=Math.min(137,Math.max(125,x.sodium));let meld=3.78*Math.log(bili)+11.2*Math.log(inr)+9.57*Math.log(creat)+6.43;meld=Math.min(40,Math.max(6,meld));const total=Math.round(Math.min(40,Math.max(6,meld+1.32*(137-na)-.033*meld*(137-na))));return result(total,total>=30?'Gravidade muito alta':total>=20?'Gravidade alta':total>=10?'Gravidade intermediária':'Menor pontuação','Usar políticas vigentes de transplante e avaliação hepatológica; tratar complicações independentemente do escore.',`bili=${bili}; INR=${inr}; creat=${creat}; Na=${na}; MELD(i)=${meld.toFixed(2)}`,total>=20?'high':total>=10?'medium':'low');},limits:'Políticas de alocação podem usar MELD 3.0 ou regras de exceção; esta é a fórmula clássica MELD-Na. Não aplicar em anticoagulação sem cautela.',sources:[R.meld]}));
priorityScores.push(continuous({id:'nafld-fibrosis-score',name:'NAFLD Fibrosis Score',specialty:'Clínica médica',population:'Adultos com DHGNA/MASLD',subtitle:'Risco de fibrose avançada',range:'Índice contínuo',scope:'Adultos com esteatose metabólica em avaliação de fibrose; resultados intermediários exigem segundo método.',fields:[meta(n('age','Idade (anos)',18,100,1)),meta(n('bmi','IMC (kg/m²)',10,80,.1)),meta(y('diabetes','Hiperglicemia/diabetes')),meta(n('ast','AST (U/L)',1,2000,.1)),meta(n('alt','ALT (U/L)',1,2000,.1)),meta(n('platelet','Plaquetas (10⁹/L)',10,1000,1)),meta(n('albumin','Albumina (g/dL)',1,6,.1))],formula:'−1,675 + 0,037×idade + 0,094×IMC + 1,13×diabetes + 0,99×AST/ALT − 0,013×plaquetas − 0,66×albumina.',compute:x=>{const total=-1.675+.037*x.age+.094*x.bmi+1.13*x.diabetes+.99*(x.ast/x.alt)-.013*x.platelet-.66*x.albumin,label=total< -1.455?'Baixa probabilidade de fibrose avançada':total>.676?'Alta probabilidade de fibrose avançada':'Zona indeterminada';return result(total,label,total< -1.455?'Seguir estratégia de baixo risco conforme diretriz e contexto.':'Realizar método de segunda linha/elastografia e considerar hepatologia.',`AST/ALT=${(x.ast/x.alt).toFixed(3)}`,total>.676?'high':total>=-1.455?'medium':'low');},limits:'Não usar na hepatite aguda ou fora da população prevista. Idade extrema altera desempenho; diretrizes atuais podem preferir FIB-4 como primeira linha.',sources:[R.nfs]}));
priorityScores.push(make({id:'gahs',name:'Glasgow Alcoholic Hepatitis Score',specialty:'Clínica médica',population:'Adultos com hepatite alcoólica',subtitle:'GAHS · prognóstico',max:12,range:'5–12',scope:'Adultos com diagnóstico de hepatite alcoólica. Usar valores na admissão ou dia 7 conforme o protocolo estudado.',fields:[s('age','Idade',[[1,'<50 anos'],[2,'≥50 anos']]),s('wbc','Leucócitos',[[1,'<15 ×10⁹/L'],[2,'≥15 ×10⁹/L']]),s('urea','Ureia',[[1,'<5 mmol/L'],[2,'≥5 mmol/L']]),s('pt','Razão do tempo de protrombina',[[1,'<1,5'],[2,'1,5–2,0'],[3,'>2,0']]),s('bili','Bilirrubina',[[1,'<125 µmol/L'],[2,'125–250 µmol/L'],[3,'>250 µmol/L']])],formula:'Soma de cinco componentes; total 5–12.',bands:[b(8,'Abaixo de 9','medium','Avaliar gravidade global, infecção, lesão renal e elegibilidade terapêutica.'),b(12,'Prognóstico desfavorável','high','≥9 identifica maior risco; discutir tratamento e monitorização especializada.')],limits:'Unidades são mmol/L e µmol/L. Não define sozinho corticoide; excluir infecção, sangramento e contraindicações e acompanhar resposta.',sources:[R.gahs]}));

priorityScores.forEach(score=>{score.wave4=true});

// Rodada documental Soberania: só candidatos suficientemente verificados entram no catálogo.
const priorityById=id=>priorityScores.find(score=>score.id===id);
priorityById("hestia").scope="Adultos ≥18 anos com TEP aguda sintomática objetivamente confirmada. Resultado negativo exige avaliação clínica, concordância do paciente, anticoagulação adequada e equipe/seguimento disponíveis.";
priorityById("hestia").fields.find(f=>f.id==="item0").hint="Instabilidade: considerar PAS <100 mmHg com FC >100/min, ou condição que requer UTI; julgamento clínico prevalece.";
priorityById("hestia").fields.find(f=>f.id==="item2").hint="Exemplos: sangramento gastrointestinal nos últimos 14 dias, AVC <4 semanas, cirurgia <2 semanas, distúrbio hemorrágico ou plaquetas <75×10⁹/L, PAS >180 ou PAD >110 mmHg.";
priorityById("hestia").fields.find(f=>f.id==="item6").hint="Exemplos: infecção, neoplasia ou ausência de suporte para tratamento em casa.";
priorityById("hestia").fields.find(f=>f.id==="item7").hint="ClCr calculado pela fórmula de Cockcroft–Gault; não substituir automaticamente por eGFR.";
priorityById("hestia").fields.find(f=>f.id==="item8").hint="Insuficiência hepática grave: avaliação clínica, segundo a definição do protocolo.";
priorityById("csrs").scope="Pacientes ≥16 anos com síncope verdadeira, apresentados à emergência até 24 h após o episódio, após avaliação e sem causa grave identificada no atendimento.";
priorityById("csrs").fields.find(f=>f.id==="vasovagal").hint="Episódio desencadeado por ambiente quente e cheio, ortostatismo prolongado, medo, emoção ou dor.";
priorityById("csrs").fields.find(f=>f.id==="heart").hint="Doença coronária/valvar, cardiomiopatia, insuficiência cardíaca, ritmo não sinusal no atendimento ou arritmia atrial/ventricular documentada/dispositivo implantado.";
priorityById("csrs").fields.find(f=>f.id==="bp").hint="Qualquer PAS entre triagem e decisão de destino; limites estritos <90 ou >180 mmHg.";
priorityById("csrs").fields.find(f=>f.id==="troponin").hint="Valor acima do percentil 99 do ensaio local; documentar dosagem/ausência de dosagem conforme protocolo.";
priorityById('clinical-frailty-scale').population='Adultos ≥65 anos · CFS v2.0';
priorityById('clinical-frailty-scale').sources=[ref('Dalhousie · CFS v2.0 · página vigente','https://www.dal.ca/sites/gmr/our-tools/clinical-frailty-scale.html'),ref('Dalhousie · CFS · orientação operacional','https://cdn.dal.ca/content/dam/dalhousie/pdf/sites/gmr/CFS-Guidance-for-Use_2020Apr06_EN.pdf'),ref('Dalhousie · CFS · população e exceção terminal','https://cdn.dal.ca/content/dam/dalhousie/pdf/sites/gmr/CFS-Top-Tips_2020Jun05_EN_Letter.pdf')];
priorityById('icdsc').fields[0].hint='RASS −4/−5 ao longo do turno: não avaliável. RASS positivo/agitação: 1; RASS 0 em todo turno: 0. RASS −1/−2/−3: 1 sem sedativo recente, ou 0 quando explicado por sedativo recente.';
priorityById('cam-icu').fields.find(f=>f.id==='f2').hint='Teste padronizado de atenção: mais de 2 erros indica desatenção.';
priorityById('cam-icu').fields.find(f=>f.id==='f3').hint='RASS diferente de 0, desde que RASS permita avaliação (≥−3).';
priorityById('cam-icu').fields.find(f=>f.id==='f4').hint='Teste padronizado de perguntas/comando: mais de 1 erro.';
applyDocumentedOverrides(priorityScores,{s,y,n,ref,b,make,ordinal,meta,result,continuous,pmc});
applyRound3Overrides(priorityScores,{s,y,n,ref,b,make,ordinal,meta,result,continuous,pmc});
applyRound4Overrides(priorityScores,{s,y,n,ref,b,make,ordinal,meta,result,continuous,pmc});
applyCurrentPriorityOverrides(priorityScores,{s,n,ref,meta,result});
priorityScores.forEach(score=>{score.source_validation=prioritySourceValidation[score.id]??null;score.review_status=score.source_validation?'DOCUMENTAL_VALIDADO':'QUARENTENA';if(!score.source_validation)score.quarantine_reason=priorityQuarantineReasons[score.id]??'Fonte operacional ou contrato clínico ainda não integralmente verificado nesta rodada; retomar revisão antes da ativação.';});
export const activePriorityScores=priorityScores.filter(score=>score.review_status==='DOCUMENTAL_VALIDADO');
export const quarantinedPriorityScores=priorityScores.filter(score=>score.review_status==='QUARENTENA');
